# hypothesis: A NotRequired key typed int | str is safe to read only after an 'in' check, and reading it without that check is a rejection the checkers may disagree on.
from typing import NotRequired, Required, TypedDict, reveal_type


class Opts(TypedDict, total=False):
    name: Required[str]
    retries: NotRequired[int | str]


class Opts2(TypedDict):
    name: str
    retries: NotRequired[int]


def describe(o: Opts) -> str:
    if 'retries' in o:
        reveal_type(o['retries'])
        return o['name'] + ':' + str(o['retries'])
    return o['name']


def bad_read(o: Opts2) -> int:
    return o['retries']  # expect-error


a: Opts = {'name': 'x'}
b: Opts = {'name': 'y', 'retries': 'three'}
c: Opts2 = {'name': 'z', 'retries': 2}
print(describe(a))
print(describe(b))
d: Opts2 = {'name': 'q'}
try:
    print(bad_read(c))
    print(bad_read(d))
except KeyError as exc:
    print('missing', exc)
